function randomAmount(number) {
  if (typeof number === "number" && (number > 0)) {
    const list = [];

    for (let i = 0; i <= number; i++) {
      list.push(singleRandom())
    };

    return list;
  } else {
    return `Error parsing ${number}!`;
  }
}

