var bon = function() {

		// 自定义标签(<if></if>, <each></each>)
		var customTagsReg     	= /(?:<if\s+.*?>(?=[^<>]*<\/?\w)|<\/if>)|<\/?each[^>]*>/g;

		// 获取if标签属性
		var ifAttributeReg		= /<if\s+(.*)>/g;

		// 获取each标签属性
		var eachAttributeReg	= /<each\s+([\w.]+)\=['"]?(\w+)['"]?(?:\s+([\w.]+)\=['"]?(\w+)['"]?)*\s*>/g;

		var cache = {};
		var fieldFn = {};

		var isIE8 = typeof window !== 'undefined' && /msie 8\.0/i.test(window.navigator.userAgent.toLowerCase());

		var symbol = '3F2D04E0-4F8U-11D3-9A0C-0A05E82C33W1';

		function addThisPrefix(exp, data) {	// 全局的表达式前加this
			return exp.replace(/\b(?:(\w+)([\w.\[\]]*))\b(?!['"])/g, function(x, prefix, other) {
				return (data[prefix] !== undefined ? 'this.' : '') + prefix + other;
			});
		}

		return {
			render: function(rawHtml, data) {
				cache[rawHtml] || this.complier(rawHtml, data);
				return cache[rawHtml].call(data);
			},
			complier: function(rawHtml, data) {

				var html = rawHtml.replace(/\s*\n\s*/g, '');//.replace(/'/g, '\\\'');

				//html.split(customTagsReg) 在ie8下会把匹配出来的空字符串给吞掉，故采用此方法兼容
				var htmlTags 	= isIE8 ? html.replace(customTagsReg, symbol).split(symbol) : html.split(customTagsReg);	// html标签
				var customTags 	= html.match(customTagsReg);	// 自定义标签（<each><if>）

				var len = Math.max(htmlTags ? htmlTags.length : 0, customTags ? customTags.length : 0);

				var statement = '';
				for(var i = 0; i < len; i ++) {
					if(htmlTags && htmlTags[i]) {
						var hTag = htmlTags[i];

						// 如果大括号的左右标记前带有反斜线, 则忽略此标记
						// js不支持逆向环视,故改用这种方式
						hTag = hTag.replace(/([^\\]|^){(.*?[^\\])(?:\:(\w+[^\\]))?}/g, function(x, other, expression, fn) {	// 取冒号前面的表达式（如果有冒号）

							expression = addThisPrefix(expression, data);
							return [other, "' + ", (fieldFn[fn] || ""), "(", expression, ") + '"].join('');
						});
						statement += "compilerTpl += ('" + hTag + "'); \n";
					}
					if(customTags && customTags[i]) {
						var cTag = customTags[i];
						cTag = cTag.replace(eachAttributeReg, function(x, arr, item, count, index) {

							arr = addThisPrefix(arr, data);

							var id 			= 'v_' + Math.random().toString(36).slice(2, 8);
							var arrVar 		= id + '_arr';
							var itemVar		= id + '_' + item + '_it';
							var indexVar	= index || (id + '_i');
							return 	'var ' + arrVar + ' = ' + arr + '; \n' +
									(count === undefined ? '' : '	var ' + count + ' = ' + arrVar + '.length;\n') +
									'for(var ' + indexVar + ' = 0; ' + indexVar + ' < ' + arrVar + '.length; ' + indexVar + ' ++) {\n' +
									'	var ' + item + ' = ' + arrVar + '[' + indexVar + '];\n';
						});

						cTag = cTag.replace(ifAttributeReg, function(x, ifExpression) {
							ifExpression = addThisPrefix(ifExpression, data);
							return 'if(' + ifExpression + ') {\n';
						}).replace(/<\/if>/g, '}\n').replace(/<\/each>/g, '}\n');

						statement += cTag;
					}
				}

				var statementHeader = 'var compilerTpl = "";\n';
				var statementFooter = 'return compilerTpl;\n';

				cache[rawHtml] = new Function(statementHeader + statement + statementFooter);
				statement = statementHeader = statementFooter = customTags = htmlTags = null;
			},
			addFun: function(fns) {
				for(var fnName in fns) {
					fieldFn[fnName] = fns[fnName];
				}
			}
		};
	}

def check_case(context):
	#Armature in pose mode
	if len(context.selected_objects) == 1 and context.selected_objects[0].type == 'ARMATURE' and context.mode == 'POSE' and len(context.selected_pose_bones) != 0:
		return True, 'BONES'
	elif len(context.selected_objects) != 0 and context.mode == 'OBJECT':
		# Objects
		types = [obj.type for obj in context.selected_objects]
		if 'ARMATURE' in types:
			types.remove('ARMATURE')
		if len(types) != 0:
			return True, 'OBJ'

	# poll KO
	return False, 'DUMMY'

def _reverse_alias_for_display(model_name: str) -> str:
    """Return the shortest configured alias for ``model_name``, or ``model_name``.

    Looks up both ``model_aliases:`` (dict-based, full DirectAlias entries)
    and ``model.aliases:`` (string-based, set via ``hermes config set``)
    from config.yaml. Multiple aliases pointing at the same model — the
    shortest wins, so ``opus47`` beats ``palantir-claude47``.
    """
    global _REVERSE_ALIAS_CACHE
    if not model_name:
        return model_name
    if _REVERSE_ALIAS_CACHE is None:
        rmap: dict[str, str] = {}
        try:
            from hermes_cli.config import load_config
            cfg = load_config() or {}
            ma = cfg.get("model_aliases")
            if isinstance(ma, dict):
                for alias, entry in ma.items():
                    if isinstance(entry, dict):
                        m = str(entry.get("model", "") or "").strip()
                        if m and (m not in rmap or len(alias) < len(rmap[m])):
                            rmap[m] = alias
            mdl = cfg.get("model", {}) or {}
            if isinstance(mdl, dict):
                simple = mdl.get("aliases")
                if isinstance(simple, dict):
                    for alias, val in simple.items():
                        if isinstance(val, str) and val.strip():
                            v = val.strip()
                            m = v.split("/", 1)[1] if "/" in v else v
                            if m and (m not in rmap or len(alias) < len(rmap[m])):
                                rmap[m] = alias
        except Exception:
            pass
        _REVERSE_ALIAS_CACHE = rmap
    return _REVERSE_ALIAS_CACHE.get(model_name, model_name)

function compileQueryParser(val) {
  var fn;

  if (typeof val === 'function') {
    return val;
  }

  switch (val) {
    case true:
    case 'simple':
      fn = querystring.parse;
      break;
    case false:
      break;
    case 'extended':
      fn = parseExtendedQueryString;
      break;
    default:
      throw new TypeError('unknown value for query parser function: ' + val);
  }

  return fn;
}

