function routeToRegExp(path, opts) {
  var keys = [];

  var pattern = path
    .replace(/([().])/g, '\\$1')
    .replace(/(\/)?:(\w+)(\*\?|[?*])?/g, function(_, slash, key, option) {
      var optional = option === '?' || option === '*?';
      var star = option === '*' || option === '*?';
      keys.push({name: key, optional: optional});
      slash = slash || '';
      return (
        (optional ? '(?:' + slash : slash + '(?:') +
        (star ? '(.+?)' : '([^/]+)') +
        (optional ? '?)?' : ')')
      );
    })
    .replace(/([/$*])/g, '\\$1');

  if (opts.ignoreTrailingSlashes) {
    pattern = pattern.replace(/\/+$/, '') + '/*';
  }

  return {
    keys: keys,
    regexp: new RegExp(
      '^' + pattern + '(?:[?#]|$)',
      opts.caseInsensitiveMatch ? 'i' : ''
    )
  };
}

var server = function(params, basePath){
    var configDefaults, config, runConfig, state, restifyServer, close, store, allowedMethods;

    configDefaults = [
        { name:'port', defaultVal: 8080 },
        { name:'logs', defaultVal: true },
        { name:'prefix', defaultVal: '' },
        { name:'path', defaultVal: '' },
        { name:'routes', defaultVal: [] }
    ];

    config = params || {};
    runConfig = {};
    state = {
        ready:false
    };
    restifyServer = null;
    close = function(cb) {
        var handler = closeHandler.bind(this);
        handler(cb);
    };
    store = null;
    allowedMethods = [
        'GET',
        'POST',
        'PATCH',
        'OPTIONS',
        'HEAD',
        'PUT',
        'DELETE'
    ];

    this.basePath = basePath;
    this.configDefaults = configDefaults;
    this.config = config;
    this.state = state;
    this.restifyServer = restifyServer;
    this.close = close;
    this.store = store;
    this.allowedMethods = allowedMethods;
}

var serializer = function(data) {
        var globals = {}

        var postData = {}; //JSON.parse(JSON.stringify(data));
        //move params that start with * to globals
        Object.keys(data).forEach(function(x) {
            if (x[0] == '*') {
                globals[x] = data[x];
            }
            else if (!x.endsWith('-gui')) { //gui only
                postData[x] = data[x];
            }
        });
        var json = JSON.stringify(postData);
        console.log(json);
        if (DEBUG) { console.log({session: session.key, json: json }) }
        var postData = '*Data=' + encodeURIComponent(json);
        if (session.key) {
            postData = postData + '&*Session=' + session.key;
        }
        Object.keys(globals).forEach(function(x) {
            postData = postData + '&' + x + '=' + encodeURIComponent(globals[x]);
        });
        return postData;
    }

