def _collect_fallback_events():
    """Aggregate fallback events recorded by every process (controller + xdist workers)."""
    events = []
    if _ci_fallback_events_dir and os.path.isdir(_ci_fallback_events_dir):
        for name in sorted(os.listdir(_ci_fallback_events_dir)):
            try:
                with open(os.path.join(_ci_fallback_events_dir, name), encoding="utf-8") as fh:
                    events.extend(line.strip() for line in fh if line.strip())
            except OSError:
                pass
    return events

function getContributors(user, repo, maxCount = 1) {
  const contributors = (
    await axios.get(
      `https://api.github.com/repos/${encodeURIComponent(user)}/${encodeURIComponent(repo)}/contributors`,
      { params: { per_page: maxCount } }
    )
  ).data;

  return Promise.all(
    contributors.map(async (contributor) => {
      return {
        ...contributor,
        ...(
          await axios.get(`https://api.github.com/users/${encodeURIComponent(contributor.login)}`)
        ).data,
      };
    })
  );
}

def sexToDecimal(ang, hparam):
    anglist = ang.split(":")
    for i in range(len(anglist)):
        anglist[i] = float(anglist[i])
    decimal = (anglist[1] / 60) + (anglist[2] / 3600)
    if anglist[0] < 0:
        ang = anglist[0] - decimal
    else:
        ang = anglist[0] + decimal
    if hparam == True:
        ang *= 15
    return ang

