function config () {
      var config = merge(
        {
          el: '#app',
          repo: '',
          maxLevel: 6,
          subMaxLevel: 0,
          loadSidebar: null,
          loadNavbar: null,
          homepage: 'README.md',
          coverpage: '',
          basePath: '',
          auto2top: false,
          name: '',
          themeColor: '',
          nameLink: window.location.pathname,
          autoHeader: false,
          executeScript: null,
          noEmoji: false,
          ga: '',
          ext: '.md',
          mergeNavbar: false,
          formatUpdated: '',
          externalLinkTarget: '_blank',
          routerMode: 'hash',
          noCompileLinks: [],
          relativePath: false
        },
        window.$docsify
      );

      var script =
        document.currentScript ||
        [].slice
          .call(document.getElementsByTagName('script'))
          .filter(function (n) { return /docsify\./.test(n.src); })[0];

      if (script) {
        for (var prop in config) {
          if (hasOwn.call(config, prop)) {
            var val = script.getAttribute('data-' + hyphenate(prop));

            if (isPrimitive(val)) {
              config[prop] = val === '' ? true : val;
            }
          }
        }

        if (config.loadSidebar === true) {
          config.loadSidebar = '_sidebar' + config.ext;
        }
        if (config.loadNavbar === true) {
          config.loadNavbar = '_navbar' + config.ext;
        }
        if (config.coverpage === true) {
          config.coverpage = '_coverpage' + config.ext;
        }
        if (config.repo === true) {
          config.repo = '';
        }
        if (config.name === true) {
          config.name = '';
        }
      }

      window.$docsify = config;

      return config
    }

function lookup(name) {
  var path;
  var roots = [].concat(this.root);

  debug('lookup "%s"', name);

  for (var i = 0; i < roots.length && !path; i++) {
    var root = roots[i];

    // resolve the path
    var loc = resolve(root, name);
    var dir = dirname(loc);
    var file = basename(loc);

    // resolve the file
    path = this.resolve(dir, file);
  }

  return path;
}

def _is_ephemeral_scaffolding(msg: Any) -> bool:
    """Return True when ``msg`` is internal recovery scaffolding that must never
    be persisted to the durable transcript (SQLite session store or JSON log)."""
    return isinstance(msg, dict) and any(
        msg.get(flag) for flag in _EPHEMERAL_SCAFFOLDING_FLAGS
    )

function isBuffer(val) {
  return (
    val !== null &&
    !isUndefined(val) &&
    val.constructor !== null &&
    !isUndefined(val.constructor) &&
    isFunction(val.constructor.isBuffer) &&
    val.constructor.isBuffer(val)
  );
}

